 _mid(){const hrs=Array.isArray(this.config.daily_hours)?this.config.daily_hours:Array(24).fill(0);const mh=Math.max(1,...hrs);this.shadowRoot.getElementById('hours').innerHTML=hrs.map((v,h)=>`<div><b>${v}</b><i style="height:${Math.max(3,Math.round(v/mh*100))}%"></i><small>${String(h).padStart(2,'0')}</small></div>`).join('');const cats=[...this._m.cats].sort((a,b)=>b.today-a.today||b.month-a.month).slice(0,7),mxT=Math.max(1,...cats.map(c=>c.today)),mxM=Math.max(1,...cats.map(c=>c.month)),mxH=Math.max(1,...cats.map(c=>c.history));this.shadowRoot.getElementById('matrix').innerHTML=`<div class="matrixhead"><span></span><span>Categoria</span><span>Hoje</span><span>Mês</span><span>Histórico</span></div>`+cats.map((c,i)=>{const col=this._color(c,i);return`<div class="matrixrow" style="--c:${col}"><span class="ci">${this._icon(c.prefix)}</span><b>${c.prefix}</b><div class="mcell"><i style="width:${Math.round(c.today/mxT*100)}%"></i><span>${c.today}</span></div><div class="mcell"><i style="width:${Math.round(c.month/mxM*100)}%"></i><span>${c.month}</span></div><div class="mcell"><i style="width:${Math.round(c.history/mxH*100)}%"></i><span>${c.history}</span></div></div>`}).join('');const top=[...this._m.autos].sort((a,b)=>(b.counter.today||0)-(a.counter.today||0)||(b.last||0)-(a.last||0)).slice(0,5);this.shadowRoot.getElementById('top').innerHTML=top.map((a,i)=>this._row(i+1,a,this.config.daily_complete?a.counter.today:'—')).join('');const last=[...this._m.autos].filter(a=>a.last).sort((a,b)=>b.last-a.last).slice(0,5);this.shadowRoot.getElementById('last').innerHTML=last.map(a=>this._row('◉',a,a.last.toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'}))).join('');const ins=[];if(this._m.never)ins.push(`${this._m.never} automações nunca executadas`);if(this._m.noCode)ins.push(`${this._m.noCode} automações realmente sem código`);const man=this._m.cats.find(c=>c.prefix==='MAN');if(man)ins.push(`MAN: ${Object.entries(man.subs).map(([k,v])=>k+' '+v).join(' • ')||'sem subcategorias'}`);if(this._m.off)ins.push(`${this._m.off} automações desativadas`);this.shadowRoot.getElementById('insights').innerHTML=ins.slice(0,5).map((x,i)=>`<div><span>${['◉','△','⚒','◇'][i]}</span><p>${x}</p></div>`).join('')}
 _bottom(){const states=this._hass?Object.values(this._hass.states):[],un=states.filter(x=>x.state==='unavailable').length,uk=states.filter(x=>x.state==='unknown').length,ms=[['AUTOMAÇÕES',this._m.total,'status-automations'],['ENTIDADES',states.length,'status-entities'],['INDISPONÍVEIS',un,'status-unavailable'],['UNKNOWN',uk,'status-unknown']];this.shadowRoot.getElementById('status').innerHTML=ms.map(([l,v,a],i)=>`<div class="status-card-clickable" data-action="${a}" role="button" tabindex="0" aria-label="Abrir detalhes de ${l}"><small>${l}</small><strong>${v}</strong><svg viewBox="0 0 100 24"><polyline points="${i%2?'0,18 14,20 28,11 42,14 57,6 72,13 86,7 100,4':'0,20 14,16 27,19 42,8 57,14 72,5 86,10 100,3'}"/></svg></div>`).join('');const checks=this._checks();this.shadowRoot.getElementById('auditmini').innerHTML=checks.slice(0,5).map(c=>`<div><span>${c.ok?'✓':'!'}</span><p>${c.name}</p><em>${c.value}</em></div>`).join('');this.shadowRoot.getElementById('catlist').innerHTML=this._m.cats.slice(0,8).map((c,i)=>`<div style="--cc:${this._color(c,i)}"><span class="ico">${this._icon(c.prefix)}</span><b>${c.prefix}</b><span>${c.label}</span><em>${c.total}</em></div>`).join('')}
